$ErrorActionPreference = 'Stop'
$compiler = Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\csc.exe'
& $compiler /nologo /target:winexe /optimize+ /platform:anycpu /reference:System.Drawing.dll /reference:System.Windows.Forms.dll /reference:System.Management.dll /reference:System.Xml.dll /reference:System.Net.Http.dll /reference:System.Web.Extensions.dll /win32icon:"$PSScriptRoot\Halo.ico" /win32manifest:"$PSScriptRoot\app.manifest" /resource:"$PSScriptRoot\Halo.ico,Halo.Icon" /resource:"$PSScriptRoot\logo.png,Halo.Logo" /out:"$PSScriptRoot\Halo.exe" "$PSScriptRoot\Halo.cs" "$PSScriptRoot\Studio.cs" "$PSScriptRoot\StudioTests.cs" "$PSScriptRoot\AssemblyInfo.cs" "$PSScriptRoot\BuildInfo.cs" "$PSScriptRoot\Updater.cs"
if ($LASTEXITCODE -ne 0) { throw 'La compilation de Halo a échoué.' }
